// MOCK: Simulate storing the form submission
// In production: write to Google Sheets, Notion, Airtable, or a DB
const raw = $input.first().json;
const submission = {
  fullName: raw.fullName || raw['Full Name'] || 'Unknown',
  email: raw.email || raw['Email Address'] || 'unknown@example.com',
  department: raw.department || raw['Department'] || 'Unknown',
  submittedAt: new Date().toISOString(),
  storedIn: 'mock_store (demo only)'
};
console.log('MOCK STORE:', JSON.stringify(submission));
return [{ json: { success: true, submission } }];

